impl StatementLayout {
    pub(crate) fn build(program: &ProgramIdentity, plan: &ActionPlan, build: CompilerBuild) -> Result<Self, CompileError> {
        use HeaderField as H;
        use SlotEncoding as E;
        let mut b = Builder { slots: Vec::new(), offset: 0 };
        b.push(SlotKind::Header(H::RelationVersion), E::Small, "header.relation_version".into());
        b.push(SlotKind::Header(H::ProgramHash), E::Digest, "header.program_hash".into());
        b.push(SlotKind::Header(H::ProfileDigest), E::Digest, "header.profile_digest".into());
        b.push(SlotKind::Header(H::ActionIndex), E::Small, "header.action_index".into());
        b.push(SlotKind::Header(H::ShapeDigest), E::Digest, "header.shape_digest".into());
        b.push(SlotKind::Header(H::CompilerBuild), E::Digest, "header.compiler_build".into());
        b.push(SlotKind::Header(H::LogicalWork), E::UInt, "header.logical_work".into());
        if plan.cap == CapBinding::PublicCap {
            b.push(SlotKind::Header(H::Cap), E::UInt, "header.cap".into());
        }
        for (i, s) in plan.inputs.iter().enumerate() {
            b.push(SlotKind::Input { index: i }, E::of(s.ty), format!("input.{}", s.name));
        }
        for (phase, post) in [("pre", false), ("post", true)] {
            for (i, s) in plan.states.iter().enumerate() {
                let kind = if post { SlotKind::PostState { index: i } } else { SlotKind::PreState { index: i } };
                b.push(kind, E::of(s.ty), format!("{phase}.state.{}", s.name));
            }
            for (i, c) in plan.cells.iter().enumerate() {
                let kind = if post { SlotKind::PostCell { index: i } } else { SlotKind::PreCell { index: i } };
                b.push(kind, E::UInt, format!("{phase}.cell.{}.{}", c.asset_name, c.account));
            }
            for (i, d) in plan.duties.iter().enumerate() {
                let (p, a) = if post {
                    (SlotKind::PostDutyPresent { index: i }, SlotKind::PostDutyAmount { index: i })
                } else {
                    (SlotKind::PreDutyPresent { index: i }, SlotKind::PreDutyAmount { index: i })
                };
                b.push(p, E::Bool, format!("{phase}.duty.{}.present", d.name));
                b.push(a, E::UInt, format!("{phase}.duty.{}.amount", d.name));
            }
        }
        for (i, e) in plan.effects.iter().enumerate() {
            let label = effect_label(i, e);
            match e {
                EffectShape::State { ty, .. } => {
                    b.push(SlotKind::Effect { index: i, role: EffectRole::StateBefore }, E::of(*ty), format!("{label}.before"));
                    b.push(SlotKind::Effect { index: i, role: EffectRole::StateAfter }, E::of(*ty), format!("{label}.after"));
                }
                EffectShape::Transfer { .. } | EffectShape::Fee { .. } => {
                    b.push(SlotKind::Effect { index: i, role: EffectRole::Amount }, E::UInt, format!("{label}.amount"));
                }
                EffectShape::Liability { .. } => {
                    b.push(SlotKind::Effect { index: i, role: EffectRole::DutyBefore }, E::UInt, format!("{label}.before"));
                    b.push(SlotKind::Effect { index: i, role: EffectRole::DutyAfter }, E::UInt, format!("{label}.after"));
                }
                EffectShape::Emit { ty, .. } => {
                    b.push(SlotKind::Effect { index: i, role: EffectRole::EmitValue }, E::of(*ty), format!("{label}.value"));
                }
            }
        }
        if plan.accounting == AccountingBinding::GrossDebitAndFees {
            for &cell in &plan.debit_cells {
                let c = &plan.cells[cell];
                b.push(SlotKind::GrossDebit { cell }, E::Wide, format!("accounting.{}.{}.gross_debit", c.asset_name, c.account));
                b.push(SlotKind::FeesPaid { cell }, E::Wide, format!("accounting.{}.{}.fees_paid", c.asset_name, c.account));
            }
        }

impl Builder {
    fn push(&mut self, kind: SlotKind, encoding: SlotEncoding, label: String) {
        self.slots.push(Slot { kind, encoding, offset: self.offset, label });
        self.offset += encoding.width();
    }

let Builder { slots, offset } = b;
let shape_digest = identity::digest_of(&ShapeDescriptor {
    format: "mori-r1cs-shape/1",
    relation_format: crate::RELATION_FORMAT,
    relation_version: crate::RELATION_VERSION,
    program_hash: program.program_hash,
    plan,
    slots: slots.iter().map(|s| (s.kind, s.encoding, s.label.as_str())).collect(),
})?;
let header = HeaderValues {
    relation_version: crate::RELATION_VERSION,
    program_hash: program.program_hash,
    profile_digest: identity::profile_digest()?,
    action_index: plan.action_index,
    shape_digest,
    compiler_build_digest: build.digest()?,
    logical_work: plan.logical_work,
};
Ok(Self { header, slots, field_count: offset })

pub fn encode<F: PrimeField>(&self, plan: &ActionPlan, values: &TransitionValues) -> Result<Vec<F>, MappingError> {
    check_values(plan, values)?;
    let summary = accounting_summary(plan, values);
    let mut out = Vec::with_capacity(self.field_count);
    for slot in &self.slots {
        let fields: Vec<F> = match slot.kind {
            SlotKind::Header(HeaderField::Cap) => {
                uint_fields(values.cap.ok_or_else(|| MappingError::Cap("cap slot without a claimed cap".into()))?.0)
            }
            SlotKind::Header(field) => self.header_fields(field).expect("non-cap header field"),
            SlotKind::Input { index } => value_fields(&values.inputs[index]),
            SlotKind::PreState { index } => value_fields(&values.pre.states[index]),
            SlotKind::PostState { index } => value_fields(&values.post.states[index]),
            SlotKind::PreCell { index } => uint_fields(values.pre.cells[index].0),
            SlotKind::PostCell { index } => uint_fields(values.post.cells[index].0),
            SlotKind::PreDutyPresent { index } => vec![fe_bool(values.pre.duties[index].present)],
            SlotKind::PreDutyAmount { index } => uint_fields(values.pre.duties[index].amount.0),
            SlotKind::PostDutyPresent { index } => vec![fe_bool(values.post.duties[index].present)],
            SlotKind::PostDutyAmount { index } => uint_fields(values.post.duties[index].amount.0),
            SlotKind::Effect { index, role } => effect_fields(&values.effects[index], role)?,
            SlotKind::GrossDebit { cell } => wide_fields(summary_for(&summary, cell)?.1),
            SlotKind::FeesPaid { cell } => wide_fields(summary_for(&summary, cell)?.2),
        };
        if fields.len() != slot.encoding.width() {
            return Err(MappingError::Shape(format!("slot {} encodes {} fields, layout says {}", slot.label, fields.len(), slot.encoding.width())));
        }
        out.extend(fields);
    }
    debug_assert_eq!(out.len(), self.field_count);
    Ok(out)

pub(crate) fn uint_fields<F: PrimeField>(v: u128) -> Vec<F> {
    vec![fe(v & MASK64), fe(v >> 64)]
}

pub(crate) fn digest_fields<F: PrimeField>(d: &Digest32) -> Vec<F> {
    let (hi, lo) = d.halves();
    vec![fe(hi), fe(lo)]
}

fn wide_fields<F: PrimeField>(w: Wide) -> Vec<F> {
    vec![fe(w.lo & MASK64), fe(w.lo >> 64), fe(u128::from(w.top))]
}

fn value_fields<F: PrimeField>(v: &Value) -> Vec<F> {
    match v {
        Value::UInt(UInt(n)) => uint_fields(*n),
        Value::Bool(b) => vec![fe_bool(*b)],
    }

fn check_type(v: &Value, ty: Type, what: &str) -> Result<(), MappingError> {
    if v.ty() == ty { Ok(()) } else { Err(MappingError::Shape(format!("{what}: expected {ty:?}, got {:?}", v.ty()))) }
}

fn check_body(plan: &ActionPlan, body: &BodyValues, phase: &str) -> Result<(), MappingError> {
    if body.states.len() != plan.states.len() || body.cells.len() != plan.cells.len() || body.duties.len() != plan.duties.len() {
        return Err(MappingError::Shape(format!("{phase} body counts differ from the plan")));
    }
    for (v, s) in body.states.iter().zip(&plan.states) {
        check_type(v, s.ty, &format!("{phase} state {}", s.name))?;
    }
    for (d, k) in body.duties.iter().zip(&plan.duties) {
        if !d.present && d.amount.0 != 0 {
            return Err(MappingError::Shape(format!("{phase} duty {} is absent with a nonzero amount", k.name)));
        }
    }
    Ok(())
}

pub(crate) fn check_values(plan: &ActionPlan, values: &TransitionValues) -> Result<(), MappingError> {
    if values.inputs.len() != plan.inputs.len() {
        return Err(MappingError::Shape("input count differs from the plan".into()));
    }
    for (v, s) in values.inputs.iter().zip(&plan.inputs) {
        check_type(v, s.ty, &format!("input {}", s.name))?;
    }
    check_body(plan, &values.pre, "pre")?;
    check_body(plan, &values.post, "post")?;
    if values.effects.len() != plan.effects.len() {
        return Err(MappingError::Shape("effect count differs from the plan".into()));
    }
    for (i, (e, s)) in values.effects.iter().zip(&plan.effects).enumerate() {
        let ok = match (s, e) {
            (EffectShape::State { ty, .. }, EffectValues::State { before, after }) => before.ty() == *ty && after.ty() == *ty,
            (EffectShape::Transfer { .. } | EffectShape::Fee { .. }, EffectValues::Amount(_)) => true,
            (EffectShape::Liability { .. }, EffectValues::Duty { .. }) => true,
            (EffectShape::Emit { ty, .. }, EffectValues::Emit(v)) => v.ty() == *ty,
            _ => false,
        };
        if !ok {
            return Err(MappingError::Shape(format!("effect {i} value does not match its shape")));
        }
    }
    match (plan.cap, values.cap) {
        (CapBinding::PublicCap, Some(_)) | (CapBinding::NotBound, None) => Ok(()),
        (CapBinding::PublicCap, None) => Err(MappingError::Cap("relation binds a public cap; none claimed".into())),
        (CapBinding::NotBound, Some(_)) => Err(MappingError::Cap("relation binds no cap; one was claimed".into())),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum StatementAdapter {
    /// TEST-ONLY direct field statement. Not a claim ABI (see module docs).
    DirectFieldV0,
    /// Placeholder for the frozen, unreviewed claimant-bound ABI v1. Always refuses.
    ClaimantBoundAbiV1Pending,
    /// P3S1 PROPOSED (unreviewed, unadopted): MRG16-PVC ABI v2. Two public inputs, the
    /// big-endian halves of an in-circuit BLAKE2b-256 of the ABI v2 statement (constant
    /// header, free context bytes, every body slot bound to its wire). See [`crate::abi2`]
    /// and `candidate/docs/ABI-V2.md`. Compile options are fixed by
    /// [`crate::abi2::options_ok`]; whole-program Emit is refused by
    /// [`initial_ledger_target_admits`], which this variant calls (review F-10 wiring for
    /// this adapter only). Proving needs a [`crate::abi2::ContextV2`]
    /// ([`crate::CompiledRelation::assignment_v2`], [`crate::CompiledRelation::circuit_v2`]).
    SettlementHashV2,
}

impl StatementAdapter {
    /// Adapter-level admission of a program. The direct test adapter admits every
    /// program the compiler lowers (Emit included); the pending ABI admits none.
    pub fn admits(&self, program: &Program) -> Result<(), AdapterError> {
        match self {
            Self::DirectFieldV0 => Ok(()),
            Self::ClaimantBoundAbiV1Pending => Err(AdapterError::Unadopted(ABI_V1_PENDING)),
            Self::SettlementHashV2 => initial_ledger_target_admits(program),
        }
    }

pub fn initial_ledger_target_admits(program: &Program) -> Result<(), AdapterError> {
    for action in &program.actions {
        for (ordinal, statement) in action.statements.iter().enumerate() {
            if let Statement::Emit { name, .. } = statement {
                return Err(AdapterError::TargetRefusal(format!(
                    "initial ledger target refuses whole-program Emit: action {:?} statement {ordinal} emits {name:?}",
                    action.name
                )));
            }
        }
    }
    Ok(())
}

/// Number of public inputs a verifier supplies.
pub fn public_input_count(&self, layout: &StatementLayout) -> Result<usize, AdapterError> {
    match self {
        Self::DirectFieldV0 => Ok(layout.field_count),
        Self::ClaimantBoundAbiV1Pending => Err(AdapterError::Unadopted(ABI_V1_PENDING)),
        Self::SettlementHashV2 => Ok(2),
    }
}

/// The public inputs of a claimed transition, in instance order.
pub fn public_inputs<F: PrimeField>(&self, layout: &StatementLayout, plan: &ActionPlan, values: &TransitionValues) -> Result<Vec<F>, MappingError> {
    match self {
        Self::DirectFieldV0 => layout.encode(plan, values),
        Self::ClaimantBoundAbiV1Pending => Err(MappingError::Adapter(AdapterError::Unadopted(ABI_V1_PENDING))),
        Self::SettlementHashV2 => Err(MappingError::Adapter(AdapterError::Unadopted(V2_NEEDS_CONTEXT))),
    }
}

pub(crate) fn bind<F: PrimeField>(
    &self,
    cs: &mut Cs<F>,
    layout: &StatementLayout,
    wires: &[SlotWire<F>],
    claimed: Option<&[F]>,
) -> Result<(), BindError> {
    match self {
        Self::DirectFieldV0 => {
            if wires.len() != layout.slots.len() {
                return Err(BindError::Adapter(AdapterError::Shape("wire count differs from slot count".into())));
            }
            if claimed.is_some_and(|c| c.len() != layout.field_count) {
                return Err(BindError::Adapter(AdapterError::Shape("claimed public vector length differs from the layout".into())));
            }
            let start = cs.num_constraints();
            cs.push("bind".into());
            for (slot, wire) in layout.slots.iter().zip(wires) {
                let limbs = wire.limbs(slot.encoding).map_err(BindError::Adapter)?;
                for (k, limb) in limbs.iter().enumerate() {
                    let x = cs.input(claimed.map(|c| c[slot.offset + k]))?;
                    cs.enforce_eq(&Lc::var(x), limb)?;
                }
            }
            cs.pop();
            cs.record("binding".into(), start);
            Ok(())
        }
        Self::ClaimantBoundAbiV1Pending => Err(BindError::Adapter(AdapterError::Unadopted(ABI_V1_PENDING))),
        Self::SettlementHashV2 => Err(BindError::Adapter(AdapterError::Unadopted(V2_BINDS_IN_CIRCUIT))),
    }
}

match relation.adapter {
    StatementAdapter::SettlementHashV2 => {
        let consts = relation.abi2.as_ref().ok_or_else(|| SynthFailure::Shape("missing ABI v2 constants".into()))?;
        let honest = match (assignment, context) {
            (None, _) => None,
            (Some(a), Some(ctx)) => {
                let body = abi2::body_bytes(layout, plan, &a.values).map_err(|e| SynthFailure::Shape(e.to_string()))?;
                Some(abi2::statement_bytes(consts, ctx, &body).map_err(|e| SynthFailure::Shape(e.to_string()))?)
            }
            (Some(_), None) => return Err(SynthFailure::Shape("SettlementHashV2 needs a ContextV2 to prove".into())),
        };
        abi2::bind_v2(&mut cs, consts, layout, &wires, honest.as_deref(), assignment.map(|a| a.public.as_slice()))?;
    }
    _ => relation.adapter.bind(&mut cs, layout, &wires, assignment.map(|a| a.public.as_slice()))?,

pub fn options_ok(options: &CompileOptions) -> Result<(), CompileError> {
    if options.cap != CapBinding::NotBound {
        return Err(CompileError::Option("SettlementHashV2 requires CapBinding::NotBound".into()));
    }
    if options.accounting != AccountingBinding::GrossDebitAndFees {
        return Err(CompileError::Option("SettlementHashV2 requires AccountingBinding::GrossDebitAndFees".into()));
    }
    if options.frame != FrameCells::TouchedOnly {
        return Err(CompileError::Option(
            "SettlementHashV2 requires FrameCells::TouchedOnly; the target enforces the frame over the complete datum".into(),
        ));
    }
    Ok(())
}

pub const STMT_TAG: &[u8; 16] = b"MRG16-PVC-STMT-2";
pub const FAMILY_V2: &[u8; 32] = b"MRG16-PVC-FAM2-G16-BLS-ARK04-HL2";
pub const SHAPE_TAG: &[u8; 16] = b"MRG16-PVC-SHP-02";
/// Bytes before the body.
pub const HEADER_LEN: usize = 343;

/// Per-proof context bytes: hashed into the statement, never interpreted in-circuit.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ContextV2 {
    pub vk_digest: [u8; 32],
    pub claimant_vkh: [u8; 28],
    pub network_id: u8,
    pub settle_hash: [u8; 28],
    pub thread_id: [u8; 32],
    pub consumed_txid: [u8; 32],
    pub consumed_ix: u16,
    pub seq: u64,
    pub catalogue_digest: [u8; 32],
    pub intents_digest: [u8; 32],
}

impl ContextV2 {
    fn bytes(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(HEADER_LEN - 116);
        out.extend_from_slice(&self.vk_digest);
        out.extend_from_slice(&self.claimant_vkh);
        out.push(self.network_id);
        out.extend_from_slice(&self.settle_hash);
        out.extend_from_slice(&self.thread_id);
        out.extend_from_slice(&self.consumed_txid);
        out.extend_from_slice(&self.consumed_ix.to_be_bytes());
        out.extend_from_slice(&self.seq.to_be_bytes());
        out.extend_from_slice(&self.catalogue_digest);
        out.extend_from_slice(&self.intents_digest);
        out
    }

fn push_u16(out: &mut Vec<u8>, n: usize, what: &str) -> Result<(), CompileError> {
    let n = u16::try_from(n).map_err(|_| too_long(what))?;
    out.extend_from_slice(&n.to_be_bytes());
    Ok(())
}

fn push_lp(out: &mut Vec<u8>, b: &[u8], what: &str) -> Result<(), CompileError> {
    push_u16(out, b.len(), what)?;
    out.extend_from_slice(b);
    Ok(())
}

fn ty_byte(ty: Type) -> u8 {
    match ty {
        Type::UInt => 0,
        Type::Bool => 1,
    }
}

pub fn sorted_assets(program: &Program) -> Vec<AssetId> {
    let mut ids: Vec<AssetId> = program.assets.iter().map(|a| a.identity.clone()).collect();
    ids.sort();
    ids.dedup();
    ids
}

/// `MRG16-PVC-SHP-02` bytes (ABI-V2.md section 4) of a planned action.
pub fn shape_bytes(program: &Program, plan: &ActionPlan) -> Result<Vec<u8>, CompileError> {
    let assets = sorted_assets(program);
    let asset_index = |id: &AssetId| -> Result<usize, CompileError> {
        assets.iter().position(|a| a == id).ok_or_else(|| CompileError::Bound("plan asset outside the program".into()))
    };
    let mut out = SHAPE_TAG.to_vec();
    push_u16(&mut out, assets.len(), "asset list")?;
    for a in &assets {
        push_lp(&mut out, a.network.as_bytes(), "asset network")?;
        push_lp(&mut out, a.issuer.as_bytes(), "asset issuer")?;
        push_lp(&mut out, a.reference.as_bytes(), "asset reference")?;
        out.push(a.scale);
    }
    push_u16(&mut out, plan.states.len(), "state list")?;
    for s in &plan.states {
        push_lp(&mut out, s.name.as_bytes(), "state name")?;
        out.push(ty_byte(s.ty));
    }
    push_u16(&mut out, plan.inputs.len(), "input list")?;
    for s in &plan.inputs {
        push_lp(&mut out, s.name.as_bytes(), "input name")?;
        out.push(ty_byte(s.ty));
    }
    push_u16(&mut out, plan.cells.len(), "cell list")?;
    for c in &plan.cells {
        push_u16(&mut out, asset_index(&c.asset)?, "asset index")?;
        push_lp(&mut out, c.account.as_bytes(), "account")?;
    }
    push_u16(&mut out, plan.duties.len(), "duty list")?;
    for d in &plan.duties {
        push_lp(&mut out, d.name.as_bytes(), "duty name")?;
        push_u16(&mut out, asset_index(&d.asset)?, "asset index")?;
        push_lp(&mut out, d.debtor.as_bytes(), "debtor")?;
        push_lp(&mut out, d.creditor.as_bytes(), "creditor")?;
    }
    push_u16(&mut out, plan.effects.len(), "effect list")?;
    for e in &plan.effects {
        match e {
            EffectShape::State { name, .. } => {
                out.push(0);
                let k = plan.state_index(name).ok_or_else(|| CompileError::Bound("state effect outside the plan".into()))?;
                push_u16(&mut out, k, "state index")?;
            }
            EffectShape::Transfer { from_cell, to_cell, .. } | EffectShape::Fee { from_cell, to_cell, .. } => {
                out.push(if e.is_fee() { 2 } else { 1 });
                push_u16(&mut out, *from_cell, "cell index")?;
                push_u16(&mut out, *to_cell, "cell index")?;
            }
            EffectShape::Liability { duty, origin, .. } => {
                out.push(3);
                push_u16(&mut out, *duty, "duty index")?;
                out.push(match origin {
                    DutyOrigin::Accrue => 0,
                    DutyOrigin::Discharge => 1,
                });
            }
            EffectShape::Emit { .. } => {
                return Err(CompileError::Unsupported {
                    construct: "Statement::Emit",
                    reason: "SettlementHashV2 applies the initial ledger target Emit refusal".into(),
                });
            }
        }
    }
    push_u16(&mut out, plan.debit_cells.len(), "debit cells")?;
    for c in &plan.debit_cells {
        push_u16(&mut out, *c, "cell index")?;
    }
    out.extend_from_slice(&plan.statement_count.to_be_bytes());
    let action = &program.actions[usize::from(plan.action_index)];
    let liability_statements = action.statements.iter().filter(|s| matches!(s, Statement::Liability { .. })).count();
    push_u16(&mut out, liability_statements, "liability statements")?;
    push_lp(&mut out, plan.action.as_bytes(), "action name")?;
    out.extend_from_slice(&plan.action_index.to_be_bytes());
    Ok(out)

/// Body length in bytes of a layout (every non-header slot).
pub fn body_len(layout: &StatementLayout) -> Result<usize, CompileError> {
    let mut n = 0usize;
    for slot in &layout.slots {
        n += match (slot.kind.is_header(), slot.encoding) {
            (true, _) => 0,
            (false, SlotEncoding::UInt) => 16,
            (false, SlotEncoding::Bool) => 1,
            (false, SlotEncoding::Wide) => 18,
            (false, other) => return Err(CompileError::Bound(format!("unexpected body slot encoding {other:?}"))),
        };
    }
    Ok(n)
}

pub(crate) fn constants(program: &Program, plan: &ActionPlan, layout: &StatementLayout, predicate: [u8; 32]) -> Result<AbiV2Constants, CompileError> {
    let shape_bytes = shape_bytes(program, plan)?;
    let shape_digest = blake2b::blake2b256(&shape_bytes);
    let body_len = u32::try_from(body_len(layout)?).map_err(|_| CompileError::Bound("ABI v2 body exceeds u32".into()))?;
    Ok(AbiV2Constants { predicate_digest: predicate, shape_bytes, shape_digest, body_len })
}

fn value_bytes(v: &Value) -> Vec<u8> {
    match v {
        Value::UInt(UInt(n)) => n.to_be_bytes().to_vec(),
        Value::Bool(b) => vec![u8::from(*b)],
    }
}

fn wide_bytes(w: Wide) -> Vec<u8> {
    let mut out = w.top.to_be_bytes().to_vec();
    out.extend_from_slice(&w.lo.to_be_bytes());
    out
}

/// Host encoding of the statement body for a claimed transition (honest proposal only;
/// the circuit binds every byte to its slot wire).
pub fn body_bytes(layout: &StatementLayout, plan: &ActionPlan, values: &TransitionValues) -> Result<Vec<u8>, MappingError> {
    let summary = accounting_summary(plan, values);
    let row = |cell: usize| summary.iter().find(|(c, _, _)| *c == cell).copied().ok_or_else(|| MappingError::Shape(format!("no accounting row for cell {cell}")));
    let mut out = Vec::new();
    for slot in &layout.slots {
        let bytes: Vec<u8> = match slot.kind {
            SlotKind::Header(_) => continue,
            SlotKind::Input { index } => value_bytes(&values.inputs[index]),
            SlotKind::PreState { index } => value_bytes(&values.pre.states[index]),
            SlotKind::PostState { index } => value_bytes(&values.post.states[index]),
            SlotKind::PreCell { index } => values.pre.cells[index].0.to_be_bytes().to_vec(),
            SlotKind::PostCell { index } => values.post.cells[index].0.to_be_bytes().to_vec(),
            SlotKind::PreDutyPresent { index } => vec![u8::from(values.pre.duties[index].present)],
            SlotKind::PreDutyAmount { index } => values.pre.duties[index].amount.0.to_be_bytes().to_vec(),
            SlotKind::PostDutyPresent { index } => vec![u8::from(values.post.duties[index].present)],
            SlotKind::PostDutyAmount { index } => values.post.duties[index].amount.0.to_be_bytes().to_vec(),
            SlotKind::Effect { index, role } => {
                use crate::statement::EffectRole as R;
                match (&values.effects[index], role) {
                    (EffectValues::State { before, .. }, R::StateBefore) => value_bytes(before),
                    (EffectValues::State { after, .. }, R::StateAfter) => value_bytes(after),
                    (EffectValues::Amount(a), R::Amount) => a.0.to_be_bytes().to_vec(),
                    (EffectValues::Duty { before, .. }, R::DutyBefore) => before.0.to_be_bytes().to_vec(),
                    (EffectValues::Duty { after, .. }, R::DutyAfter) => after.0.to_be_bytes().to_vec(),
                    _ => return Err(MappingError::Shape(format!("effect {index} has no role {role:?}"))),
                }
            }
            SlotKind::GrossDebit { cell } => wide_bytes(row(cell)?.1),
            SlotKind::FeesPaid { cell } => wide_bytes(row(cell)?.2),
        };
        out.extend(bytes);
    }
    Ok(out)
}

/// Complete statement bytes.
pub fn statement_bytes(consts: &AbiV2Constants, ctx: &ContextV2, body: &[u8]) -> Result<Vec<u8>, MappingError> {
    if body.len() != consts.body_len as usize {
        return Err(MappingError::Shape(format!("body has {} bytes, the relation fixes {}", body.len(), consts.body_len)));
    }
    let mut s = Vec::with_capacity(HEADER_LEN + body.len());
    s.extend_from_slice(STMT_TAG);
    s.extend_from_slice(FAMILY_V2);
    s.extend_from_slice(&consts.predicate_digest);
    s.extend_from_slice(&consts.shape_digest);
    s.extend(ctx.bytes());
    s.extend_from_slice(&consts.body_len.to_be_bytes());
    s.extend_from_slice(body);
    debug_assert_eq!(s.len(), HEADER_LEN + body.len());
    Ok(s)
}

pub fn statement_v2(&self, values: &TransitionValues, context: &ContextV2) -> Result<Vec<u8>, MappingError> {
    let consts = self
        .abi2
        .as_ref()
        .ok_or(MappingError::Adapter(AdapterError::Unadopted("statement_v2 needs the SettlementHashV2 adapter")))?;
    crate::statement::check_values(&self.plan, values)?;
    let body = abi2::body_bytes(&self.layout, &self.plan, values)?;
    abi2::statement_bytes(consts, context, &body)
}

/// P3S1: the two ABI v2 public inputs of a claimed transition in a context.
pub fn public_inputs_v2<F: PrimeField>(&self, values: &TransitionValues, context: &ContextV2) -> Result<Vec<F>, MappingError> {
    self.check_field::<F>().map_err(MappingError::Field)?;
    Ok(abi2::public_inputs::<F>(&self.statement_v2(values, context)?))
}

/// P3S1: an ABI v2 assignment (public = the two digest halves).
pub fn assignment_v2<F: PrimeField>(&self, values: TransitionValues, context: &ContextV2) -> Result<Assignment<F>, MappingError> {
    let public = self.public_inputs_v2::<F>(&values, context)?;
    Ok(Assignment { values, public })

/// The two public inputs `[int_be(d[0..16]), int_be(d[16..32])]`, d = BLAKE2b-256(stmt).
pub fn public_inputs<F: PrimeField>(statement: &[u8]) -> Vec<F> {
    let d = blake2b::blake2b256(statement);
    let mut hi = [0u8; 16];
    let mut lo = [0u8; 16];
    hi.copy_from_slice(&d[..16]);
    lo.copy_from_slice(&d[16..]);
    vec![fe(u128::from_be_bytes(hi)), fe(u128::from_be_bytes(lo))]
}

pub(crate) fn bind_v2<F: PrimeField>(
    cs: &mut Cs<F>,
    consts: &AbiV2Constants,
    layout: &StatementLayout,
    wires: &[SlotWire<F>],
    honest: Option<&[u8]>,
    claimed: Option<&[F]>,
) -> Result<(), BindError> {
    if wires.len() != layout.slots.len() {
        return Err(BindError::Adapter(AdapterError::Shape("wire count differs from slot count".into())));
    }
    let total = HEADER_LEN + consts.body_len as usize;
    if honest.is_some_and(|h| h.len() != total) {
        return Err(BindError::Adapter(AdapterError::Shape("honest statement length differs from the relation".into())));
    }
    if claimed.is_some_and(|c| c.len() != 2) {
        return Err(BindError::Adapter(AdapterError::Shape("SettlementHashV2 has exactly two public inputs".into())));
    }
    let start = cs.num_constraints();
    cs.push("abi2".into());
    let mut bits: Vec<Bit<F>> = Vec::with_capacity(8 * total);
    const_bytes(STMT_TAG, &mut bits);
    const_bytes(FAMILY_V2, &mut bits);
    const_bytes(&consts.predicate_digest, &mut bits);
    const_bytes(&consts.shape_digest, &mut bits);
    free_bytes(cs, honest.map(|h| &h[112..339]), 339 - 112, &mut bits)?;
    const_bytes(&consts.body_len.to_be_bytes(), &mut bits);
    let mut at = HEADER_LEN;
    for (slot, wire) in layout.slots.iter().zip(wires) {
        if slot.kind.is_header() {
            continue;
        }
        let width = match slot.encoding {
            SlotEncoding::UInt => 16,
            SlotEncoding::Bool => 1,
            SlotEncoding::Wide => 18,
            _ => return Err(BindError::Adapter(AdapterError::Shape("unexpected body slot encoding".into()))),
        };
        let h = honest.map(|h| &h[at..at + width]);
        match (wire, slot.encoding) {
            (SlotWire::U(u), SlotEncoding::UInt) => uint_bytes(cs, u, h, &mut bits)?,
            (SlotWire::B(b), SlotEncoding::Bool) => {
                // The Bool wire is already 0 or 1; its byte is (b, 0, ..., 0) LSB first.
                bits.push(Bit { lc: b.lc.clone(), val: b.val, konst: b.konst });
                for _ in 1..8 {
                    bits.push(Bit::constant(false));
                }
            }
            (SlotWire::W(w), SlotEncoding::Wide) => wide_bytes_in(cs, w, h, &mut bits)?,
            _ => return Err(BindError::Adapter(AdapterError::Shape(format!("slot {} wire does not match its encoding", slot.label)))),
        }
        at += width;
    }
    if bits.len() != 8 * total {
        return Err(BindError::Adapter(AdapterError::Shape("statement bit count differs from the relation".into())));
    }
    let digest = blake2b::blake2b256_gadget(cs, &bits)?;
    for (k, from) in [0usize, 16].into_iter().enumerate() {
        let x = cs.input(claimed.map(|c| c[k]))?;
        cs.enforce_eq(&Lc::var(x), &blake2b::digest_half_lc(&digest, from))?;
    }
    cs.pop();
    cs.record("abi2-binding".into(), start);
    Ok(())
}

fn const_bytes<F: PrimeField>(bytes: &[u8], bits: &mut Vec<Bit<F>>) {
    for b in bytes {
        for j in 0..8 {
            bits.push(Bit::constant((b >> j) & 1 == 1));
        }
    }
}

/// Free witness bytes (context): booleanized bits, honest values from `honest`.
fn free_bytes<F: PrimeField>(cs: &mut Cs<F>, honest: Option<&[u8]>, n: usize, bits: &mut Vec<Bit<F>>) -> Result<(), BindError> {
    for k in 0..n {
        for j in 0..8 {
            let val = honest.map(|h| (h[k] >> j) & 1 == 1);
            bits.push(blake2b::alloc_bit(cs, "abi2.ctx", val)?);
        }
    }
    Ok(())
}

/// Bytes of a limb (big-endian, `n` bytes) bound to its linear combination: booleanized
/// bits whose weighted sum equals the limb. A constant limb yields constant bits.
fn limb_bytes<F: PrimeField>(
    cs: &mut Cs<F>,
    limb: &Lc<F>,
    konst: Option<u128>,
    n: usize,
    honest: Option<&[u8]>,
    bits: &mut Vec<Bit<F>>,
) -> Result<(), BindError> {
    if let Some(k) = konst {
        let be = k.to_be_bytes();
        const_bytes(&be[16 - n..], bits);
        return Ok(());
    }
    let mut sum = Lc::zero();
    for k in 0..n {
        for j in 0..8 {
            let val = honest.map(|h| (h[k] >> j) & 1 == 1);
            let bit = blake2b::alloc_bit(cs, "abi2.body", val)?;
            let weight = 8 * (n - 1 - k) + j;
            sum = sum.plus(&bit.lc.scaled(fe(1u128 << weight)));
            bits.push(bit);
        }
    }
    cs.enforce_eq(&sum, limb)?;
    Ok(())
}

fn uint_bytes<F: PrimeField>(cs: &mut Cs<F>, u: &UIntW<F>, honest: Option<&[u8]>, bits: &mut Vec<Bit<F>>) -> Result<(), BindError> {
    let (khi, klo) = match u.konst {
        Some(k) => (Some(k >> 64), Some(k & u128::from(u64::MAX))),
        None => (None, None),
    };
    limb_bytes(cs, &u.hi, khi, 8, honest.map(|h| &h[0..8]), bits)?;
    limb_bytes(cs, &u.lo, klo, 8, honest.map(|h| &h[8..16]), bits)
}

fn wide_bytes_in<F: PrimeField>(cs: &mut Cs<F>, w: &WideW<F>, honest: Option<&[u8]>, bits: &mut Vec<Bit<F>>) -> Result<(), BindError> {
    limb_bytes(cs, &w.top, None, 2, honest.map(|h| &h[0..2]), bits)?;
    limb_bytes(cs, &w.mid, None, 8, honest.map(|h| &h[2..10]), bits)?;
    limb_bytes(cs, &w.lo, None, 8, honest.map(|h| &h[10..18]), bits)
}

#[derive(Debug, Clone)]
pub struct StagedAdmission {
    staged: StagedProgram,
    source_sha256: Digest32,
}

/// D-13 (canonical reconstruction cap) is split between two recorded votes:
/// `Some(plan_total[a])` (pr54-stage-owner-tests-and-design DESIGN-VOTES D-13) and
/// `None` (pr54-owner-suite independent Opus review §9). This compiler selects
/// neither: a future staged relation carries the stored cap as a public, caller-chosen
/// slot and never fabricates a reconstruction default.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum StoredCapParameter {
    /// The continuation's stored cap (`Option<UInt>`) is a public statement slot:
    /// a presence Bool and a UInt, absent exactly `(false, 0)`.
    ExplicitPublicSlot,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub enum SegmentEntry {
    /// Segment 0: inputs seed the environment; the pre frame is locally Idle.
    Start { inputs: Vec<CaptureSlot> },
    /// Segment `site`: captures and event binders seed the environment; the guard at
    /// `guard_ordinal` must evaluate to true as its own Step.
    Resume { site: u16, label: String, guard_ordinal: u16, captures: Vec<CaptureSlot>, binders: Vec<StageBinder> },
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub enum SegmentExit {
    /// The next await is reached: entry charge 1, captures in that site's layout.
    Await { site: u16, label: String, ordinal: u16, captures: Vec<CaptureSlot> },
    /// The action completes; the post frame is Idle with no captures.
    Complete,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct StagedSegmentShape {
    pub segment: u16,
    pub entry: SegmentEntry,
    /// Half-open source ordinals executed by this segment (a resume starts at its
    /// guard; the exit await's ordinal is excluded).
    pub statement_start: u16,
    pub statement_end: u16,
    pub exit: SegmentExit,
    /// From the actual stage plan (`stage/cost.rs:70-145`).
    pub segment_cost: UInt,
    pub committed_before: UInt,
    pub committed_after: UInt,
    /// Attempted work of a false guard at this resume site (NotAdvanced relation).
    pub not_advanced_attempted: Option<UInt>,
    /// Effect kinds in statement order, including Emit (never dropped).
    pub effect_kinds: Vec<String>,
    pub has_emit: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct StagedActionPlan {
    pub action: String,
    pub action_index: u16,
    pub statement_count: u16,
    pub plan_total: UInt,
    pub segments: Vec<StagedSegmentShape>,
}

    pub fn lowering_plan(&self) -> Result<StagedLoweringPlan, CompileError> {
        let program = self.staged.program();
        let stage_plan = self.staged.plan();
        let mut actions = Vec::with_capacity(stage_plan.actions.len());
        for (index, (action, ap)) in program.actions.iter().zip(&stage_plan.actions).enumerate() {
            if ap.action != action.name || ap.segment_cost.len() != ap.sites.len() + 1 || ap.committed_before.len() != ap.sites.len() + 1 {
                return Err(CompileError::Bound(format!("stage plan for {:?} is not the admitted plan", action.name)));
            }
            let action_index = u16::try_from(index).map_err(|_| CompileError::Bound("action index exceeds u16".into()))?;
            let inputs: Vec<CaptureSlot> = action
                .inputs
                .iter()
                .enumerate()
                .map(|(i, input)| CaptureSlot { name: input.name.clone(), ty: input.ty, origin: mori_core::stage::Origin::Input, ordinal: i as u16 })
                .collect();
            let mut segments = Vec::with_capacity(ap.sites.len() + 1);
            for segment in 0..=ap.sites.len() {
                let (entry, start) = if segment == 0 {
                    (SegmentEntry::Start { inputs: inputs.clone() }, 0u16)
                } else {
                    let site = &ap.sites[segment - 1];
                    (
                        SegmentEntry::Resume {
                            site: site.site,
                            label: site.label.clone(),
                            guard_ordinal: site.ordinal,
                            captures: site.captures.clone(),
                            binders: site.binders.clone(),
                        },
                        site.ordinal,
                    )
                };
                let (exit, end) = match ap.sites.get(segment) {
                    Some(next) => (
                        SegmentExit::Await { site: next.site, label: next.label.clone(), ordinal: next.ordinal, captures: next.captures.clone() },
                        next.ordinal,
                    ),
                    None => (SegmentExit::Complete, ap.statement_count),
                };
                let statements = action
                    .statements
                    .get(usize::from(start)..usize::from(end))
                    .ok_or_else(|| CompileError::Bound("segment range outside the action".into()))?;
                let effect_kinds: Vec<String> = statements.iter().filter_map(effect_kind).collect();
                let has_emit = statements.iter().any(|s| matches!(s, Statement::Emit { .. }));
                let not_advanced_attempted = match statements.first() {
                    Some(guard @ Statement::Await { .. }) if segment > 0 => Some(UInt(plan::statement_cost(program, guard)?)),
                    _ => None,
                };
                let before = ap.committed_before[segment];
                let cost = ap.segment_cost[segment];
                let after = before.0.checked_add(cost.0).map(UInt).ok_or_else(|| CompileError::Bound("committed work exceeds u128".into()))?;
                segments.push(StagedSegmentShape {
                    segment: segment as u16,
                    entry,
                    statement_start: start,
                    statement_end: end,
                    exit,
                    segment_cost: cost,
                    committed_before: before,
                    committed_after: after,
                    not_advanced_attempted,
                    effect_kinds,
                    has_emit,
                });
            }
            actions.push(StagedActionPlan {
                action: action.name.clone(),
                action_index,
                statement_count: ap.statement_count,
                plan_total: ap.plan_total,
                segments,
            });
        }
        Ok(StagedLoweringPlan {
            language: program.language.clone(),
            semantics: program.semantics.clone(),
            logical_cost_profile: mori_core::stage::LOGICAL_COST_PROFILE_2.into(),
            stage_plan_format: mori_core::stage::STAGE_PLAN_FORMAT.into(),
            continuation_format: mori_core::stage::CONTINUATION_FORMAT.into(),
            program_hash: Digest32(self.staged.program_hash()),
            plan_hash: Digest32(self.staged.plan_hash()),
            source_sha256: self.source_sha256,
            stored_cap: StoredCapParameter::ExplicitPublicSlot,
            actions,
            remaining: STAGED_REMAINING.iter().map(|s| (*s).to_string()).collect(),
        })
    }
}

pub fn compile_source<F: PrimeField>(source: &str, options: CompileOptions, adapter: StatementAdapter) -> Result<CompiledRelation, CompileError> {
    match frontend::admit_source(source)? {
        Admitted::Core1(admitted) => compile::<F>(admitted, options, adapter),
        Admitted::Staged2(staged) => Err(CompileError::StagedNotLowered(Box::new(staged.lowering_plan()?))),
    }
}

    pub fn lowering_plan(&self) -> Result<StagedLoweringPlan, CompileError> {
        let program = self.staged.program();
        let stage_plan = self.staged.plan();
        let mut actions = Vec::with_capacity(stage_plan.actions.len());
        for (index, (action, ap)) in program.actions.iter().zip(&stage_plan.actions).enumerate() {
            if ap.action != action.name || ap.segment_cost.len() != ap.sites.len() + 1 || ap.committed_before.len() != ap.sites.len() + 1 {
                return Err(CompileError::Bound(format!("stage plan for {:?} is not the admitted plan", action.name)));
            }
            let action_index = u16::try_from(index).map_err(|_| CompileError::Bound("action index exceeds u16".into()))?;
            let inputs: Vec<CaptureSlot> = action
                .inputs
                .iter()
                .enumerate()
                .map(|(i, input)| CaptureSlot { name: input.name.clone(), ty: input.ty, origin: mori_core::stage::Origin::Input, ordinal: i as u16 })
                .collect();
            let mut segments = Vec::with_capacity(ap.sites.len() + 1);
            for segment in 0..=ap.sites.len() {
                let (entry, start) = if segment == 0 {
                    (SegmentEntry::Start { inputs: inputs.clone() }, 0u16)
                } else {
                    let site = &ap.sites[segment - 1];
                    (
                        SegmentEntry::Resume {
                            site: site.site,
                            label: site.label.clone(),
                            guard_ordinal: site.ordinal,
                            captures: site.captures.clone(),
                            binders: site.binders.clone(),
                        },
                        site.ordinal,
                    )
                };
                let (exit, end) = match ap.sites.get(segment) {
                    Some(next) => (
                        SegmentExit::Await { site: next.site, label: next.label.clone(), ordinal: next.ordinal, captures: next.captures.clone() },
                        next.ordinal,
                    ),
                    None => (SegmentExit::Complete, ap.statement_count),
                };
                let statements = action
                    .statements
                    .get(usize::from(start)..usize::from(end))
                    .ok_or_else(|| CompileError::Bound("segment range outside the action".into()))?;
                let effect_kinds: Vec<String> = statements.iter().filter_map(effect_kind).collect();
                let has_emit = statements.iter().any(|s| matches!(s, Statement::Emit { .. }));
                let not_advanced_attempted = match statements.first() {
                    Some(guard @ Statement::Await { .. }) if segment > 0 => Some(UInt(plan::statement_cost(program, guard)?)),
                    _ => None,
                };
                let before = ap.committed_before[segment];
                let cost = ap.segment_cost[segment];
                let after = before.0.checked_add(cost.0).map(UInt).ok_or_else(|| CompileError::Bound("committed work exceeds u128".into()))?;
                segments.push(StagedSegmentShape {
                    segment: segment as u16,
                    entry,
                    statement_start: start,
                    statement_end: end,
                    exit,
                    segment_cost: cost,
                    committed_before: before,
                    committed_after: after,
                    not_advanced_attempted,
                    effect_kinds,
                    has_emit,
                });
            }
            actions.push(StagedActionPlan {
                action: action.name.clone(),
                action_index,
                statement_count: ap.statement_count,
                plan_total: ap.plan_total,
                segments,
            });
        }
        Ok(StagedLoweringPlan {
            language: program.language.clone(),
            semantics: program.semantics.clone(),
            logical_cost_profile: mori_core::stage::LOGICAL_COST_PROFILE_2.into(),
            stage_plan_format: mori_core::stage::STAGE_PLAN_FORMAT.into(),
            continuation_format: mori_core::stage::CONTINUATION_FORMAT.into(),
            program_hash: Digest32(self.staged.program_hash()),
            plan_hash: Digest32(self.staged.plan_hash()),
            source_sha256: self.source_sha256,
            stored_cap: StoredCapParameter::ExplicitPublicSlot,
            actions,
            remaining: STAGED_REMAINING.iter().map(|s| (*s).to_string()).collect(),
        })
    }
